<?php
declare(strict_types=1);
namespace App\Controllers\Admin;
use App\Core\{Container,Csrf,Database,Request,Response,Session,View};
use App\Repositories\AcademicTrajectoryRepository;
use App\Services\AccessService;
final class AcademicTrajectoryController{
 private function repo():AcademicTrajectoryRepository{return new AcademicTrajectoryRepository(Container::get(Database::class)->connection());}
 private function csrf(Request $r):void{if(!Csrf::validate((string)$r->input('_csrf')))Response::abort(419,'CSRF inválido.');}
 public function index(Request $r):void{AccessService::require('academico.estructura.ver');$x=$this->repo();View::render('admin/academico/estructura/index',['title'=>'Estructura académica','cohorts'=>$x->cohorts(),'subjects'=>$x->subjects(),'curricula'=>$x->curricula(),'types'=>$x->subjectTypes()]);}
 public function cohortSave(Request $r):never{$this->csrf($r);AccessService::require('academico.estructura.gestionar');$d=['id'=>(int)$r->input('id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'inicio'=>trim((string)$r->input('fecha_inicio')),'fin'=>trim((string)$r->input('fecha_fin_estimada')),'activo'=>$r->input('activo')!==null?1:0];if(!$d['codigo']||!$d['nombre'])Response::abort(422,'Código y nombre son obligatorios.');$this->repo()->saveCohort($d);Response::redirect('/admin/academico/estructura');}
 public function subjectSave(Request $r):never{$this->csrf($r);AccessService::require('academico.estructura.gestionar');$d=['id'=>(int)$r->input('id'),'tipo'=>(int)$r->input('tipo_asignatura_id'),'codigo'=>strtoupper(trim((string)$r->input('codigo'))),'nombre'=>trim((string)$r->input('nombre')),'descripcion'=>trim((string)$r->input('descripcion')),'activo'=>$r->input('activo')!==null?1:0];if(!$d['tipo']||!$d['codigo']||!$d['nombre'])Response::abort(422,'Tipo, código y nombre son obligatorios.');$this->repo()->saveSubject($d);Response::redirect('/admin/academico/estructura');}
 public function curriculum(Request $r):void{AccessService::require('academico.estructura.ver');$x=$this->repo();$id=(int)$r->input('id');$m=null;foreach($x->curricula() as $z)if((int)$z['id']===$id)$m=$z;if(!$m)Response::abort(404,'Malla no encontrada.');View::render('admin/academico/estructura/malla',['title'=>'Estructura de malla','malla'=>$m,'items'=>$x->curriculumSubjects($id),'subjects'=>$x->subjects(),'levels'=>$x->levels()]);}
 public function curriculumSubjectSave(Request $r):never{$this->csrf($r);AccessService::require('academico.estructura.gestionar');$d=['malla'=>(int)$r->input('malla_id'),'asignatura'=>(int)$r->input('asignatura_id'),'nivel'=>(int)$r->input('nivel_academico_id'),'creditos'=>(float)$r->input('creditos'),'semanal'=>trim((string)$r->input('ih_semanal')),'total'=>trim((string)$r->input('ih_total')),'orden'=>(int)$r->input('orden_en_nivel'),'obligatoria'=>$r->input('obligatoria')!==null?1:0,'evaluable'=>$r->input('evaluable')!==null?1:0];if(!$d['malla']||!$d['asignatura']||!$d['nivel'])Response::abort(422,'Malla, asignatura y nivel son obligatorios.');$this->repo()->addCurriculumSubject($d);Response::redirect('/admin/academico/malla?id='.$d['malla']);}
 public function prerequisiteSave(Request $r):never{$this->csrf($r);AccessService::require('academico.estructura.gestionar');$m=(int)$r->input('malla_id');$this->repo()->addPrerequisite((int)$r->input('malla_asignatura_id'),(int)$r->input('prerrequisito_id'));Response::redirect('/admin/academico/malla?id='.$m);}
 public function student(Request $r):void{AccessService::require('academico.trayectorias.ver');$id=(int)$r->input('id');$db=Container::get(Database::class)->connection();$s=$db->prepare("SELECT e.id,e.codigo_estudiante,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre,p.numero_identificacion FROM estudiantes e JOIN personas p ON p.id=e.persona_id WHERE e.id=:id AND e.deleted_at IS NULL");$s->execute(['id'=>$id]);$student=$s->fetch();if(!$student)Response::abort(404,'Estudiante no encontrado.');$x=$this->repo();$ctx=$x->admissionContext($id);View::render('admin/academico/trayectorias/student',['title'=>'Trayectoria académica','student'=>$student,'context'=>$ctx,'trajectories'=>$x->trajectories($id),'curricula'=>$ctx&&$ctx['carrera_id']?$x->availableCurricula((int)$ctx['carrera_id'],isset($ctx['sede_id'])?(int)$ctx['sede_id']:null):[],'cohorts'=>$x->cohorts(),'states'=>$x->trajectoryStates(),'levels'=>$x->levels()]);}
 public function trajectorySave(Request $r):never{$this->csrf($r);AccessService::require('academico.trayectorias.gestionar');$d=['student'=>(int)$r->input('estudiante_id'),'carrera'=>(int)$r->input('carrera_id'),'malla'=>(int)$r->input('malla_id'),'cohorte'=>(int)$r->input('cohorte_id'),'estado'=>(int)$r->input('estado_trayectoria_id'),'tipo_ingreso'=>(int)$r->input('tipo_ingreso_id'),'sede'=>(int)$r->input('sede_id'),'modalidad'=>(int)$r->input('modalidad_academica_id'),'fecha'=>trim((string)$r->input('fecha_inicio')),'nivel'=>(int)$r->input('nivel_referencial_id')];if(!$d['student']||!$d['carrera']||!$d['malla']||!$d['estado']||!$d['fecha'])Response::abort(422,'Estudiante, carrera, malla, estado y fecha son obligatorios.');$this->repo()->createTrajectory($d,(int)(Session::get('auth_user')['id']??0));Response::redirect('/admin/academico/trayectoria?id='.$d['student']);}
}
